def count_zeros(Q):
    """Counts the number of zeros in the decimal representation of Q."""
    return str(Q).count('0')

max_A = 0

# Case M has 3 digits (M in [111, 999])
print("--- 3 Digit M Investigation ---")
for M in range(111, 1000):
    # Check if M consists only of non-zero digits
    if any(int(d) == 0 for d in str(M)):
        continue

    # Only need to test N <= M
    for N in range(1, M + 1):
        Q = M // N
        A = count_zeros(Q)
        if A > max_A:
            max_A = A
            print(f"New Max A found: {max_A} with M={M}, N={N}, Q={Q}")

# Case M has 4 digits (M in [1111, 9999])
print("\n--- 4 Digit M Investigation ---")
max_A_4digit = 0
for M in range(1111, 10000):
    # Check if M consists only of non-zero digits
    if any(int(d) == 0 for d in str(M)):
        continue

    for N in range(1, M + 1):
        Q = M // N
        A = count_zeros(Q)
        if A > max_A_4digit:
            max_A_4digit = A
            print(f"New Max A found: {A} with M={M}, N={N}, Q={Q}")

print(f"\nMax A for 3 digits: {max_A}")
print(f"Max A for 4 digits: {max_A_4digit}")

